      return;
    }
    this.selectedProperties.set(selection);
    this.loadPage(1);
  }

  protected onSortSelectionChange(value: string): void {
    if (this.loading()) {
      return;
    }
    switch (value) {
      case 'price-asc':
        this.sortBy.set('price');
        this.sortDir.set('asc');
        break;
      case 'price-desc':
        this.sortBy.set('price');
        this.sortDir.set('desc');
        break;
      case 'name-asc':
        this.sortBy.set('name');
        this.sortDir.set('asc');
        break;
      case 'name-desc':
        this.sortBy.set('name');
        this.sortDir.set('desc');
        break;
      default:
        this.sortBy.set(undefined);
        this.sortDir.set(undefined);
    }
    this.loadPage(1);
  }

  protected onSearchSubmit(term: string): void {
    if (this.loading()) {
      return;
    }
    const trimmed = term.trim();
    this.q.set(trimmed || undefined);
    this.loadPage(1);
  }

  private loadPage(page: number): void {
    this.loading.set(true);
    this.error.set(false);
    this.productsApi
      .getProducts(
        page,
        this.selectedCategoryId(),
        this.selectedSubcategoryId(),
        this.sortBy(),
        this.sortDir(),
        this.q(),
      )
      .subscribe({
        next: (result) => {
          this.page.set(result.page);
          this.result.set(result);
          this.loading.set(false);
        },
        error: () => {
          this.loading.set(false);
          this.error.set(true);
        },
      });
  }
}

