    expect(productsApiMock.getProducts).toHaveBeenLastCalledWith(1, undefined, undefined, undefined, undefined, 'Kopfhörer', undefined);
    expect(compiled.querySelector('.product-list__name')?.textContent).toBe('Kopfhörer');
